#!/usr/bin/env python3
"""
五大联赛赛程推送脚本 - 获取未来几天内喜欢的球队赛程，通过 PushPlus 推送到微信
数据源: TheSportsDB API (免费，无需注册)
"""

import requests
import datetime
import time
import sys
import unicodedata
import urllib3
from typing import Dict, List, Optional, Tuple

urllib3.disable_warnings()

# ==================== 配置区域 ====================
PUSHPLUS_TOKEN = "2f1d3808db024a8e828afb6e003dc64b"

FAVORITE_TEAMS = [
    "Arsenal",
    "Liverpool",
    "Manchester United",
    "Manchester City",
    "Chelsea",
    "Atletico Madrid",
    "Real Madrid",
    "Bayern Munich",
    "AC Milan",
    "Barcelona",
    "Paris Saint-Germain",
]

DAYS_AHEAD = 3
DEBUG = False
# ==================================================

# 球队ID映射
TEAM_IDS = {
    "Arsenal": "133604", "Liverpool": "133602", "Manchester United": "133612",
    "Manchester City": "133613", "Chelsea": "133610", "Atletico Madrid": "133729",
    "Real Madrid": "133738", "Bayern Munich": "133664", "AC Milan": "133667",
    "Barcelona": "133739", "Paris Saint-Germain": "133718",
}

# 球队中文名
TEAM_CN = {
    "Arsenal": "阿森纳", "Liverpool": "利物浦", "Manchester United": "曼联",
    "Manchester City": "曼城", "Chelsea": "切尔西", "Atletico Madrid": "马竞",
    "Atlético Madrid": "马竞", "Real Madrid": "皇马", "Bayern Munich": "拜仁",
    "AC Milan": "AC米兰", "Barcelona": "巴萨", "Paris Saint-Germain": "巴黎",
    "Tottenham Hotspur": "热刺", "Leeds United": "利兹联",
    "Fiorentina": "佛罗伦萨", "Inter Milan": "国米",
    "Birmingham City": "伯明翰", "Girona": "赫罗纳",
}

# 联赛中文名
LEAGUE_CN = {
    "Premier League": "英超", "English Premier League": "英超",
    "Bundesliga": "德甲", "German Bundesliga": "德甲",
    "Serie A": "意甲", "Italian Serie A": "意甲",
    "La Liga": "西甲", "Spanish La Liga": "西甲",
    "Ligue 1": "法甲", "French Ligue 1": "法甲",
    "Club Friendlies": "友谊赛",
    "UEFA Champions League": "欧冠", "Europa League": "欧联",
}


def normalize(s: str) -> str:
    """去掉重音符号，转为小写"""
    return unicodedata.normalize("NFKD", s).encode("ASCII", "ignore").decode().lower().strip()


def log(msg: str):
    if DEBUG:
        print(f"[DEBUG] {msg}")
    else:
        print(msg)


def get_team_cn(name_en: str) -> str:
    for eng, cn in TEAM_CN.items():
        if eng.lower() == name_en.lower():
            return cn + "(" + name_en + ")"
    return name_en


def get_league_cn(league_str: str) -> str:
    for eng, cn in LEAGUE_CN.items():
        if eng.lower() in league_str.lower():
            return cn
    return league_str


def get_today_and_range() -> Tuple[str, str, str]:
    today = datetime.date.today()
    end = today + datetime.timedelta(days=DAYS_AHEAD)
    return today.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d"), today.strftime("%Y-%m-%d %A")


def get_team_id(team_name: str) -> Optional[str]:
    for key, val in TEAM_IDS.items():
        if key.lower() == team_name.lower():
            return val
    try:
        headers = {"User-Agent": "Mozilla/5.0"}
        r = requests.get(
            "https://www.thesportsdb.com/api/v1/json/3/searchteams.php?t=" + team_name,
            headers=headers, timeout=15, verify=False
        )
        if r.status_code == 200:
            teams_data = r.json().get("teams", [])
            if teams_data:
                return teams_data[0].get("idTeam")
    except Exception:
        pass
    return None


def fetch_events(team_id: str) -> List[Dict]:
    for attempt in range(3):
        try:
            headers = {"User-Agent": "Mozilla/5.0"}
            r = requests.get(
                "https://www.thesportsdb.com/api/v1/json/3/eventsnext.php?id=" + team_id,
                headers=headers, timeout=15, verify=False
            )
            if r.status_code == 200:
                events = []
                for e in (r.json().get("events", []) or []):
                    events.append({
                        "date": e.get("dateEvent", ""),
                        "time": e.get("strTime", ""),
                        "home": e.get("strHomeTeam", ""),
                        "away": e.get("strAwayTeam", ""),
                        "league": e.get("strLeague", ""),
                        "round": e.get("intRound", ""),
                    })
                return events
            elif r.status_code == 429:
                time.sleep(2)
        except requests.exceptions.SSLError:
            time.sleep(1)
        except Exception as e:
            log("  request error(attempt " + str(attempt+1) + "/3): " + str(e))
            time.sleep(1)
    return []


def push_to_wechat(title: str, html_content: str) -> bool:
    if not PUSHPLUS_TOKEN:
        log("! Please configure PushPlus Token!")
        return False
    try:
        r = requests.post("https://www.pushplus.plus/send", json={
            "token": PUSHPLUS_TOKEN,
            "title": title,
            "content": html_content,
            "template": "html",
        }, headers={"Content-Type": "application/json"}, timeout=10)
        result = r.json()
        if result.get("code") == 200:
            log("  Push success! Check WeChat.")
            return True
        else:
            log("  Push failed: " + result.get("msg", "unknown"))
            return False
    except Exception as e:
        log("  Push error: " + str(e))
        return False


def main():
    print("=" * 45)
    print("  五大联赛赛程推送")
    print("=" * 45)
    print()

    today_str, end_str, today_display = get_today_and_range()
    log("  Date: " + today_display)
    log("  Range: " + today_str + " ~ " + end_str)
    print()

    all_events = []
    fav_normalized = [normalize(t) for t in FAVORITE_TEAMS]

    log(" Querying TheSportsDB API...")

    for team_name in FAVORITE_TEAMS:
        team_id = get_team_id(team_name)
        if not team_id:
            log("  Cannot find ID for " + team_name + ", skip")
            continue

        events = fetch_events(team_id)
        if events:
            count = 0
            for e in events:
                date_str = e.get("date", "")
                if not (today_str <= date_str <= end_str):
                    continue
                home = normalize(e.get("home", ""))
                away = normalize(e.get("away", ""))
                if any(f in home or f in away for f in fav_normalized):
                    all_events.append(e)
                    count += 1
            log("  " + team_name + ": " + str(len(events)) + " matches, " + str(count) + " in " + str(DAYS_AHEAD) + " days")
        else:
            log("  " + team_name + ": no data")

        time.sleep(0.3)

    # Deduplicate
    seen = set()
    unique = []
    for e in all_events:
        key = (e["date"], e["home"], e["away"])
        if key not in seen:
            seen.add(key)
            unique.append(e)

    unique.sort(key=lambda x: (x.get("date", ""), x.get("time", "")))

    print()
    print("=" * 45)

    if unique:
        log("  Found " + str(len(unique)) + " matches")
    else:
        log("  No matches in next " + str(DAYS_AHEAD) + " days")

    print()

    # Build content
    content_lines = []

    # Collect favorite teams found
    found = set()
    for e in unique:
        for t in [e.get("home", ""), e.get("away", "")]:
            if any(f in normalize(t) for f in fav_normalized):
                found.add(t)
    if found:
        content_lines.append("== " + " ".join(get_team_cn(t) for t in sorted(found)) + " ==\n")

    if not unique:
        content_lines.append("No matches in the next " + str(DAYS_AHEAD) + " days.\nNew season starts mid-August.\n")

    by_date = {}
    for e in unique:
        d = e.get("date", "")
        if d not in by_date:
            by_date[d] = []
        by_date[d].append(e)

    for d in sorted(by_date.keys()):
        weekday = ""
        try:
            dt = datetime.datetime.strptime(d, "%Y-%m-%d")
            weekdays_cn = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
            weekday = " (" + weekdays_cn[dt.weekday()] + ")"
        except Exception:
            pass

        content_lines.append("\n" + d + weekday)
        content_lines.append("-" * 30)

        for e in by_date[d]:
            time_str = e.get("time", "").strip()
            t = (" " + time_str[:5]) if time_str else " TBD"
            home = e.get("home", "?")
            away = e.get("away", "?")

            def mark(x):
                if any(f in normalize(x) for f in fav_normalized):
                    return "**" + get_team_cn(x) + "**"
                return get_team_cn(x)

            league = get_league_cn(e.get("league", ""))
            rnd = e.get("round", "")
            rtext = " (R" + rnd + ")" if rnd else ""

            content_lines.append(t + "  " + mark(home) + " vs " + mark(away))
            content_lines.append("     " + league + rtext)

    content_lines.append("")
    content_lines.append("=" * 30)
    content_lines.append("Source: TheSportsDB")
    content_lines.append("Time: " + datetime.datetime.now().strftime("%Y-%m-%d %H:%M"))

    plain_text = "\n".join(content_lines)
    html_text = plain_text.replace("\n", "<br>")

    print(plain_text)
    print()

    log(" Pushing to WeChat...")
    title = "Football - My Team Fixtures (" + str(DAYS_AHEAD) + "d)"
    push_to_wechat(title, html_text)

    print()
    print("=" * 45)
    print("  Done!")
    print("=" * 45)


